const BASE_URL = 'https://ottotuhkunen.github.io/virtual-lara-airspace-data';

export function getGeojsonFile(locationKey) {
  return `${BASE_URL}/data/${locationKey}.geojson`;
}

export function getJsonFile(locationKey) {
  return `${BASE_URL}/data/${locationKey}.json`;
}

